/**
 * 范围内提交数超过 `commitLimit` 时整次创建失败（不截断），需缩小日期或调大上限。
 */
export type RepositorySyncCreate = {
    /**
     * 公开 HTTP(S) 仓库地址；file、ssh、git 协议、内联用户名密码与内网主机被拒绝。
     */
    repositoryUrl: string;
    branch?: string;
    /**
     * ISO 日期或日期时间；留空取最近 90 天。
     */
    since?: string;
    /**
     * ISO 日期或日期时间；留空取当前时间。
     */
    until?: string;
    commitLimit?: number;
    strategy?: 'auto' | 'generic-model' | 'force-train';
    /**
     * Explicit registered compatible model; requires generic-model strategy.
     */
    modelId?: string;
    /**
     * 训练方法；只在 auto 或 force-train 时可用，缺省为 logistic-regression-l2-v1。
     */
    algorithm?: string;
    splitPreset?: SplitPreset;
    maturityPolicy?: 'mature-only' | 'include-immature';
};

/**
 * 一次同步作业的完整状态。`modelStrategy` 与 `degradeReason` 回答"这次用的是哪个模型、为什么"；`trainRecords`／`trainPositives` 是训练区样本数，只在走过训练判定时有值。
 */
export type RepositorySyncView = {
    /**
     * 新普通分析为 branch，PR 专用任务为 pr，无法证明用途的历史记录为 unknown。
     */
    sourceKind: 'branch' | 'pr' | 'unknown';
    sourceSnapshotId: string | null;
    origin: 'manual' | 'automatic';
    /**
     * 创建或成功完成时冻结的真实模型特征口径。
     */
    featureSchemaVersion: string | null;
    /**
     * 请求的训练方法；使用现成模型时为空。
     */
    algorithm?: string | null;
    /**
     * 方法显示名，供记录与详情展示。
     */
    algorithmName?: string | null;
    /**
     * 成功分析冻结的风险分档规则；旧记录可能缺失。
     */
    distributionRule: string | null;
    splitPreset?: SplitPreset;
    splitPolicy?: null | SplitPolicy;
    maturityPolicy: 'mature-only' | 'include-immature' | 'legacy-unrecorded';
    maturity: {
        [key: string]: unknown;
    } | null;
    /**
     * 复用已保存特征时的来源说明；未复用时为 null。
     */
    featureSource?: {
        [key: string]: unknown;
    } | null;
    /**
     * 全局单 worker 队列中待执行的顺序，从 1 开始；执行中及终态为 null，不代表预计等待时间。
     */
    queuePosition?: number | null;
    startedAt?: string | null;
    /**
     * 从开始执行起计算的截止时间，排队时间不计入执行时限。
     */
    deadlineAt?: string | null;
    /**
     * 非空且作业仍在进行中时表示正在取消，不允许删除记录。
     */
    cancelRequestedAt?: string | null;
    repositoryId?: string | null;
    analysisBranch?: string | null;
    completedAt?: string | null;
    headCommit?: string | null;
    syncId: Uuid;
    repositoryUrl: string;
    branch: string;
    since: string | null;
    until: string | null;
    commitLimit: number | null;
    requestedStrategy: 'auto' | 'generic-model' | 'force-train';
    status: 'queued' | 'collecting' | 'registering' | 'training' | 'scoring' | 'completed' | 'failed' | 'interrupted' | 'cancelled';
    stage: 'queued' | 'collecting' | 'registering' | 'training' | 'scoring' | 'completed' | 'failed' | 'interrupted' | 'cancelled';
    datasetVersion: string | null;
    runId: string | null;
    modelId: string | null;
    modelStrategy: 'repository-trained' | 'generic-model' | null;
    degradeReason: 'fewRecords' | 'fewPositives' | 'noTestPositive' | 'noGenericModel' | 'noMatureRecords' | null;
    trainRecords: number | null;
    trainPositives: number | null;
    createdAt: string;
    updatedAt: string;
    requestId: string | null;
    error: null | {
        code: string;
        message: string;
    };
    /**
     * 入队时绑定的现成模型身份；默认切换不改变此值，自动策略实际训练时不使用它。
     */
    resolvedModelId?: string | null;
    requestedModelId?: string | null;
};

